/** Estados y códigos del dominio de liquidación. */
export type LiquidationStatus = 'APROBADA' | 'RECHAZADA' | 'PENDIENTE_APROBACION';

export type ClaimNewStatus = 'LIQUIDADO' | 'RECHAZADO' | 'PENDIENTE_REVISION';

export type RejectionReason =
  | 'POLIZA_NO_VIGENTE'
  | 'FUERA_DE_VIGENCIA'
  | 'DENUNCIA_EXTEMPORANEA'
  | 'COBERTURA_NO_CONTRATADA'
  | 'EN_PERIODO_CARENCIA'
  | 'PRIMA_EN_MORA'
  | 'BAJO_DEDUCIBLE'
  | 'SUMA_ASEGURADA_AGOTADA';

export type ApprovalReason = 'SOSPECHA_FRAUDE' | 'SUPERA_TOPE_AUTOMATICO' | 'LIQUIDACION_AUTOMATICA';

export type ReasonCode = RejectionReason | ApprovalReason;

export type ErrorCode = '' | 'ORA-20001' | 'ORA-20010';

/**
 * Motivos de rechazo que conservan las observaciones acumuladas.
 * @rule R-018
 */
const OBSERVATION_PRESERVING_REASONS: readonly RejectionReason[] = [
  'PRIMA_EN_MORA',
  'BAJO_DEDUCIBLE',
  'SUMA_ASEGURADA_AGOTADA',
];

/**
 * Indica si un rechazo conserva las observaciones acumuladas.
 * @rule R-018
 */
export function preservesObservations(reason: RejectionReason): boolean {
  return OBSERVATION_PRESERVING_REASONS.includes(reason);
}

const DAYS_IN_MONTH: readonly number[] = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
const DAYS_PER_ERA = 146097;
const EPOCH_SHIFT = 719468;

function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year: number, month: number): number {
  if (month === 2 && isLeapYear(year)) {
    return 29;
  }
  return DAYS_IN_MONTH[month - 1] ?? 0;
}

function isValidDate(year: number, month: number, day: number): boolean {
  if (month < 1 || month > 12) {
    return false;
  }
  return day >= 1 && day <= daysInMonth(year, month);
}

function toEpochDay(year: number, month: number, day: number): number {
  const shiftedYear = month <= 2 ? year - 1 : year;
  const era = Math.floor(shiftedYear / 400);
  const yearOfEra = shiftedYear - era * 400;
  const monthFromMarch = (month + 9) % 12;
  const dayOfYear = Math.floor((153 * monthFromMarch + 2) / 5) + day - 1;
  const dayOfEra =
    yearOfEra * 365 + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100) + dayOfYear;
  return era * DAYS_PER_ERA + dayOfEra - EPOCH_SHIFT;
}

/** Fecha sin hora (equivale a TRUNC(date)). Inmutable. */
export class LocalDate {
  readonly epochDay: number;

  constructor(epochDay: number) {
    this.epochDay = epochDay;
  }

  /** Interpreta 'YYYY-MM-DD' (se ignora una hora posterior). Devuelve null si es inválida. */
  static parse(text: string): LocalDate | null {
    const match = /^(\d{4})-(\d{2})-(\d{2})(?:$|[T ])/.exec(text.trim());
    if (match === null) {
      return null;
    }
    const year = parseInt(match[1] ?? '', 10);
    const month = parseInt(match[2] ?? '', 10);
    const day = parseInt(match[3] ?? '', 10);
    if (!isValidDate(year, month, day)) {
      return null;
    }
    return new LocalDate(toEpochDay(year, month, day));
  }

  /** Días naturales transcurridos desde other hasta esta fecha (this - other). */
  daysSince(other: LocalDate): number {
    return this.epochDay - other.epochDay;
  }

  isBefore(other: LocalDate): boolean {
    return this.epochDay < other.epochDay;
  }

  isAfter(other: LocalDate): boolean {
    return this.epochDay > other.epochDay;
  }
}

/** Marcas de ajuste acumuladas. Vacío equivale a NULL. */
export class Observations {
  private readonly marks: readonly string[];

  private constructor(marks: readonly string[]) {
    this.marks = marks;
  }

  static empty(): Observations {
    return new Observations([]);
  }

  /**
   * Añade una marca respetando el orden de ocurrencia.
   * @rule R-020
   */
  add(mark: string): Observations {
    return new Observations([...this.marks, mark]);
  }

  isEmpty(): boolean {
    return this.marks.length === 0;
  }

  /**
   * Texto de salida: marcas separadas por ';' o cadena vacía si es NULL.
   * @rule R-020
   */
  toOutputString(): string {
    return this.marks.join(';');
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { MissingParameterError } from '../exceptions/MissingParameterError.ts';

/** Parámetros de negocio (valor numérico por código). */
export class BusinessParameters {
  private readonly values: ReadonlyMap<string, Decimal>;

  constructor(values: ReadonlyMap<string, Decimal>) {
    this.values = values;
  }

  /**
   * Obtiene un parámetro obligatorio; si no existe aborta con MissingParameterError.
   * @rule R-002
   */
  require(code: string): Decimal {
    const value = this.values.get(code);
    if (value === undefined) {
      throw new MissingParameterError(code);
    }
    return value;
  }
}

/**
 * Señal interna del dominio: parámetro de negocio no definido.
 * ClaimLiquidationService la convierte en un resultado ORA-20010.
 * @rule R-002
 */
export class MissingParameterError extends Error {
  readonly parameterCode: string;

  constructor(parameterCode: string) {
    super(`Parametro no definido: ${parameterCode}`);
    this.name = 'MissingParameterError';
    this.parameterCode = parameterCode;
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { LocalDate } from './LocalDate.ts';

export interface ClaimData {
  readonly status: string;
  readonly amountClaimed: Decimal;
  readonly occurrenceDate: LocalDate;
  readonly reportDate: LocalDate;
}

export interface PolicyData {
  readonly status: string;
  readonly branch: string;
  readonly startDate: LocalDate;
  readonly endDate: LocalDate;
  readonly sumInsured: Decimal;
  readonly deductibleType: string;
  readonly deductibleValue: Decimal;
  readonly pendingPremium: Decimal;
}

export interface CustomerData {
  readonly category: string;
}

export interface CoverageData {
  readonly found: boolean;
  readonly limit: Decimal;
  readonly percentage: Decimal;
  readonly waitingDays: number;
}

export interface ClaimHistory {
  readonly recentLiquidatedClaimsCount: number;
  readonly totalIndemnified: Decimal;
}

/** Datos de entrada completos para liquidar un siniestro. */
export interface LiquidationRequest {
  readonly claim: ClaimData;
  readonly policy: PolicyData;
  readonly customer: CustomerData;
  readonly coverage: CoverageData;
  readonly history: ClaimHistory;
}

import type { Decimal } from '../shared/decimal.ts';
import type { Observations } from './Observations.ts';

/** Importe resultante de un paso de cálculo con las observaciones acumuladas. */
export class AdjustedAmount {
  readonly amount: Decimal;
  readonly observations: Observations;

  constructor(amount: Decimal, observations: Observations) {
    this.amount = amount;
    this.observations = observations;
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { Observations } from './Observations.ts';
import { preservesObservations } from './codes.ts';
import type {
  ClaimNewStatus,
  ErrorCode,
  LiquidationStatus,
  ReasonCode,
  RejectionReason,
} from './codes.ts';
import { claimStatusFor } from '../services/ClaimStatusMapper.ts';
import { zeroAmount } from '../services/AmountMath.ts';

export interface DecidedProps {
  readonly status: LiquidationStatus;
  readonly reasonCode: ReasonCode;
  readonly baseAmount: Decimal;
  readonly deductibleAmount: Decimal;
  readonly coveredAmount: Decimal;
  readonly withholdingAmount: Decimal;
  readonly netAmount: Decimal;
  readonly observations: Observations;
}

/** Resultado inmutable de la liquidación (incluye rechazos y errores como datos). */
export class LiquidationResult {
  readonly status: LiquidationStatus | '';
  readonly reasonCode: ReasonCode | '';
  readonly baseAmount: Decimal;
  readonly deductibleAmount: Decimal;
  readonly coveredAmount: Decimal;
  readonly withholdingAmount: Decimal;
  readonly netAmount: Decimal;
  readonly observations: Observations;
  readonly claimNewStatus: ClaimNewStatus | '';
  readonly errorCode: ErrorCode;

  private constructor(
    decided: DecidedProps | null,
    status: LiquidationStatus | '',
    reasonCode: ReasonCode | '',
    observations: Observations,
    errorCode: ErrorCode,
  ) {
    this.status = status;
    this.reasonCode = reasonCode;
    this.baseAmount = decided === null ? zeroAmount() : decided.baseAmount;
    this.deductibleAmount = decided === null ? zeroAmount() : decided.deductibleAmount;
    this.coveredAmount = decided === null ? zeroAmount() : decided.coveredAmount;
    this.withholdingAmount = decided === null ? zeroAmount() : decided.withholdingAmount;
    this.netAmount = decided === null ? zeroAmount() : decided.netAmount;
    this.observations = observations;
    this.claimNewStatus = status === '' ? '' : claimStatusFor(status);
    this.errorCode = errorCode;
  }

  /**
   * Liquidación aprobada o pendiente de aprobación, con importes calculados.
   * @rule R-019
   */
  static decided(props: DecidedProps): LiquidationResult {
    return new LiquidationResult(props, props.status, props.reasonCode, props.observations, '');
  }

  /**
   * Rechazo: importes en cero; observaciones solo en los motivos que las conservan.
   * @rule R-018
   * @rule R-019
   */
  static rejected(reason: RejectionReason, accumulated: Observations): LiquidationResult {
    const observations = preservesObservations(reason) ? accumulated : Observations.empty();
    return new LiquidationResult(null, 'RECHAZADA', reason, observations, '');
  }

  /**
   * Error de proceso (ORA-20001 / ORA-20010): sin liquidación y sin cambio de estado del siniestro.
   * @rule R-001
   * @rule R-002
   */
  static failed(errorCode: ErrorCode): LiquidationResult {
    return new LiquidationResult(null, '', '', Observations.empty(), errorCode);
  }
}

import { Decimal } from '../shared/decimal.ts';

const HUNDRED = Decimal.of(100);

/**
 * Importe cero con escala 2.
 * @rule R-021
 */
export function zeroAmount(): Decimal {
  return Decimal.of('0.00');
}

/** Indica si el valor es estrictamente mayor que cero. */
export function isPositive(value: Decimal): boolean {
  return value.gt(Decimal.of(0));
}

/**
 * amount * percentage / 100 redondeado a 2 decimales (mitad hacia arriba).
 * @rule R-021
 */
export function percentOf(amount: Decimal, percentage: Decimal): Decimal {
  return amount.times(percentage).dividedBy(HUNDRED, 2, 'HALF_UP');
}

/**
 * amount * (100 - percentage) / 100 redondeado a 2 decimales (mitad hacia arriba).
 * @rule R-021
 */
export function complementPercentOf(amount: Decimal, percentage: Decimal): Decimal {
  return amount.times(HUNDRED.minus(percentage)).dividedBy(HUNDRED, 2, 'HALF_UP');
}

import type { ClaimNewStatus, LiquidationStatus } from '../model/codes.ts';

/**
 * Estado del siniestro según el estado de la liquidación.
 * @rule R-019
 */
export function claimStatusFor(status: LiquidationStatus): ClaimNewStatus {
  if (status === 'APROBADA') {
    return 'LIQUIDADO';
  }
  if (status === 'RECHAZADA') {
    return 'RECHAZADO';
  }
  return 'PENDIENTE_REVISION';
}

import type { RejectionReason } from '../../model/codes.ts';

/** Resultado de una verificación de elegibilidad. */
export class CheckOutcome {
  readonly rejectionReason: RejectionReason | null;
  readonly mark: string | null;

  private constructor(rejectionReason: RejectionReason | null, mark: string | null) {
    this.rejectionReason = rejectionReason;
    this.mark = mark;
  }

  static passed(): CheckOutcome {
    return new CheckOutcome(null, null);
  }

  static passedWithMark(mark: string): CheckOutcome {
    return new CheckOutcome(null, mark);
  }

  static rejected(reason: RejectionReason): CheckOutcome {
    return new CheckOutcome(reason, null);
  }
}

import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import type { LiquidationRequest } from '../../model/LiquidationRequest.ts';
import type { CheckOutcome } from './CheckOutcome.ts';

/** Specification de elegibilidad previa al cálculo. */
export interface EligibilityCheck {
  evaluate(request: LiquidationRequest, params: BusinessParameters): CheckOutcome;
}

import type { LiquidationRequest } from '../../model/LiquidationRequest.ts';
import { CheckOutcome } from './CheckOutcome.ts';
import type { EligibilityCheck } from './EligibilityCheck.ts';

/** Solo se indemnizan pólizas VIGENTES. */
export class ActivePolicyCheck implements EligibilityCheck {
  /**
   * @rule R-003
   */
  evaluate(request: LiquidationRequest): CheckOutcome {
    if (request.policy.status !== 'VIGENTE') {
      return CheckOutcome.rejected('POLIZA_NO_VIGENTE');
    }
    return CheckOutcome.passed();
  }
}

import type { LiquidationRequest } from '../../model/LiquidationRequest.ts';
import { CheckOutcome } from './CheckOutcome.ts';
import type { EligibilityCheck } from './EligibilityCheck.ts';

/** La ocurrencia debe estar dentro de la vigencia (límites inclusivos). */
export class CoverageWindowCheck implements EligibilityCheck {
  /**
   * @rule R-004
   */
  evaluate(request: LiquidationRequest): CheckOutcome {
    const occurrence = request.claim.occurrenceDate;
    const outside =
      occurrence.isBefore(request.policy.startDate) || occurrence.isAfter(request.policy.endDate);
    return outside ? CheckOutcome.rejected('FUERA_DE_VIGENCIA') : CheckOutcome.passed();
  }
}

import { Decimal } from '../../shared/decimal.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import type { LiquidationRequest } from '../../model/LiquidationRequest.ts';
import { CheckOutcome } from './CheckOutcome.ts';
import type { EligibilityCheck } from './EligibilityCheck.ts';

/** Plazo máximo de denuncia: 365 días para VIDA, 30 para el resto (último día válido). */
export class ReportDeadlineCheck implements EligibilityCheck {
  /**
   * @rule R-005
   */
  evaluate(request: LiquidationRequest, params: BusinessParameters): CheckOutcome {
    const elapsedDays = request.claim.reportDate.daysSince(request.claim.occurrenceDate);
    const maxDays = this.maxDaysFor(request.policy.branch, params);
    return Decimal.of(elapsedDays).gt(maxDays)
      ? CheckOutcome.rejected('DENUNCIA_EXTEMPORANEA')
      : CheckOutcome.passed();
  }

  /**
   * @rule R-005
   */
  private maxDaysFor(branch: string, params: BusinessParameters): Decimal {
    return branch === 'VIDA'
      ? params.require('DIAS_MAX_DENUNCIA_VIDA')
      : params.require('DIAS_MAX_DENUNCIA');
  }
}

import type { LiquidationRequest } from '../../model/LiquidationRequest.ts';
import { CheckOutcome } from './CheckOutcome.ts';
import type { EligibilityCheck } from './EligibilityCheck.ts';

/** La cobertura reclamada debe estar contratada. */
export class ContractedCoverageCheck implements EligibilityCheck {
  /**
   * @rule R-006
   */
  evaluate(request: LiquidationRequest): CheckOutcome {
    return request.coverage.found
      ? CheckOutcome.passed()
      : CheckOutcome.rejected('COBERTURA_NO_CONTRATADA');
  }
}

import type { LiquidationRequest } from '../../model/LiquidationRequest.ts';
import { CheckOutcome } from './CheckOutcome.ts';
import type { EligibilityCheck } from './EligibilityCheck.ts';

/** Periodo de carencia desde el inicio de la póliza. */
export class WaitingPeriodCheck implements EligibilityCheck {
  /**
   * @rule R-007
   */
  evaluate(request: LiquidationRequest): CheckOutcome {
    const daysSinceStart = request.claim.occurrenceDate.daysSince(request.policy.startDate);
    return daysSinceStart < request.coverage.waitingDays
      ? CheckOutcome.rejected('EN_PERIODO_CARENCIA')
      : CheckOutcome.passed();
  }
}

import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import type { LiquidationRequest } from '../../model/LiquidationRequest.ts';
import { isPositive } from '../../services/AmountMath.ts';
import { CheckOutcome } from './CheckOutcome.ts';
import type { EligibilityCheck } from './EligibilityCheck.ts';

/** Morosidad de prima con tolerancia para clientes VIP. */
export class PremiumArrearsCheck implements EligibilityCheck {
  /**
   * @rule R-008
   */
  evaluate(request: LiquidationRequest, params: BusinessParameters): CheckOutcome {
    const pending = request.policy.pendingPremium;
    if (!isPositive(pending)) {
      return CheckOutcome.passed();
    }
    if (this.isWithinVipTolerance(request, params)) {
      return CheckOutcome.passedWithMark('TOLERANCIA_MORA_VIP');
    }
    return CheckOutcome.rejected('PRIMA_EN_MORA');
  }

  /**
   * @rule R-008
   */
  private isWithinVipTolerance(request: LiquidationRequest, params: BusinessParameters): boolean {
    if (request.customer.category !== 'VIP') {
      return false;
    }
    return request.policy.pendingPremium.lte(params.require('TOLERANCIA_MORA_VIP'));
  }
}

import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import type { RejectionReason } from '../../model/codes.ts';
import type { LiquidationRequest } from '../../model/LiquidationRequest.ts';
import { Observations } from '../../model/Observations.ts';
import type { EligibilityCheck } from './EligibilityCheck.ts';

export interface EligibilityOutcome {
  readonly rejectionReason: RejectionReason | null;
  readonly observations: Observations;
}

/** Evalúa las verificaciones en orden fijo; la primera que falla determina el motivo. */
export class EligibilityPipeline {
  private readonly checks: readonly EligibilityCheck[];

  constructor(checks: readonly EligibilityCheck[]) {
    this.checks = checks;
  }

  /**
   * Orden de evaluación definido por la lista inyectada (R-018).
   * @rule R-018
   */
  run(request: LiquidationRequest, params: BusinessParameters): EligibilityOutcome {
    let observations = Observations.empty();
    for (const check of this.checks) {
      const outcome = check.evaluate(request, params);
      if (outcome.rejectionReason !== null) {
        return { rejectionReason: outcome.rejectionReason, observations };
      }
      if (outcome.mark !== null) {
        observations = observations.add(outcome.mark);
      }
    }
    return { rejectionReason: null, observations };
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import { AdjustedAmount } from '../../model/AdjustedAmount.ts';
import type { Observations } from '../../model/Observations.ts';

/** Monto base: menor entre lo reclamado y el límite de cobertura. */
export class BaseAmountRule {
  /**
   * @rule R-009
   */
  calculate(claimed: Decimal, coverageLimit: Decimal, observations: Observations): AdjustedAmount {
    if (claimed.gt(coverageLimit)) {
      return new AdjustedAmount(
        coverageLimit.setScale(2, 'HALF_UP'),
        observations.add('LIMITE_COBERTURA'),
      );
    }
    return new AdjustedAmount(claimed, observations);
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import { AdjustedAmount } from '../../model/AdjustedAmount.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import type { Observations } from '../../model/Observations.ts';
import type { PolicyData } from '../../model/LiquidationRequest.ts';
import { percentOf } from '../../services/AmountMath.ts';

/** Deducible fijo o porcentual (sobre el monto base) con mínimo. */
export class DeductibleRule {
  /**
   * FIJO usa el valor de la póliza; cualquier otro tipo se trata como PORCENTAJE.
   * @rule R-010
   * @rule R-021
   */
  calculate(
    baseAmount: Decimal,
    policy: PolicyData,
    params: BusinessParameters,
    observations: Observations,
  ): AdjustedAmount {
    if (policy.deductibleType === 'FIJO') {
      return new AdjustedAmount(policy.deductibleValue, observations);
    }
    const percentual = percentOf(baseAmount, policy.deductibleValue);
    const minimum = params.require('DEDUCIBLE_MINIMO');
    if (percentual.lt(minimum)) {
      return new AdjustedAmount(minimum.setScale(2, 'HALF_UP'), observations.add('DEDUCIBLE_MINIMO'));
    }
    return new AdjustedAmount(percentual, observations);
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import { AdjustedAmount } from '../../model/AdjustedAmount.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import type { Observations } from '../../model/Observations.ts';
import { complementPercentOf, isPositive } from '../../services/AmountMath.ts';

/** Descuento VIP sobre el deducible (posterior al deducible mínimo). */
export class VipDeductibleDiscountRule {
  /**
   * @rule R-011
   * @rule R-021
   */
  apply(
    deductible: Decimal,
    customerCategory: string,
    params: BusinessParameters,
    observations: Observations,
  ): AdjustedAmount {
    if (customerCategory !== 'VIP' || !isPositive(deductible)) {
      return new AdjustedAmount(deductible, observations);
    }
    const discountPct = params.require('PCT_DESCUENTO_DED_VIP');
    return new AdjustedAmount(
      complementPercentOf(deductible, discountPct),
      observations.add('DESCUENTO_VIP'),
    );
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import { percentOf } from '../../services/AmountMath.ts';

/** Monto cubierto y detección de bajo deducible. */
export class CoveredAmountRule {
  /**
   * ROUND((base - deducible) * porcentaje_cobertura / 100, 2).
   * @rule R-012
   * @rule R-021
   */
  calculate(baseAmount: Decimal, deductible: Decimal, coveragePercentage: Decimal): Decimal {
    return percentOf(baseAmount.minus(deductible), coveragePercentage);
  }

  /**
   * Un monto cubierto <= 0 implica rechazo BAJO_DEDUCIBLE.
   * @rule R-012
   */
  isBelowDeductible(covered: Decimal): boolean {
    return covered.lte(Decimal0());
  }
}

import { Decimal } from '../../shared/decimal.ts';

function Decimal0(): Decimal {
  return Decimal.of(0);
}

import { Decimal } from '../../shared/decimal.ts';
import { AdjustedAmount } from '../../model/AdjustedAmount.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import type { Observations } from '../../model/Observations.ts';
import { complementPercentOf } from '../../services/AmountMath.ts';

/** Penalización por alta siniestralidad en los 365 días previos. */
export class FrequencyPenaltyRule {
  /**
   * @rule R-013
   * @rule R-021
   */
  apply(
    covered: Decimal,
    recentLiquidatedClaimsCount: number,
    params: BusinessParameters,
    observations: Observations,
  ): AdjustedAmount {
    const maxClaims = params.require('MAX_SINIESTROS_ANUAL');
    if (Decimal.of(recentLiquidatedClaimsCount).lt(maxClaims)) {
      return new AdjustedAmount(covered, observations);
    }
    const penaltyPct = params.require('PCT_PENALIZACION_SINIEST');
    return new AdjustedAmount(
      complementPercentOf(covered, penaltyPct),
      observations.add('PENALIZACION_SINIESTRALIDAD'),
    );
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import { AdjustedAmount } from '../../model/AdjustedAmount.ts';
import type { Observations } from '../../model/Observations.ts';
import { isPositive } from '../../services/AmountMath.ts';

/** Tope por suma asegurada remanente. */
export class SumInsuredCapRule {
  /**
   * suma_remanente = sum_insured - total_indemnified.
   * @rule R-014
   */
  remaining(sumInsured: Decimal, totalIndemnified: Decimal): Decimal {
    return sumInsured.minus(totalIndemnified);
  }

  /**
   * Sin remanente disponible (<= 0) se rechaza por SUMA_ASEGURADA_AGOTADA.
   * @rule R-014
   */
  isExhausted(remaining: Decimal): boolean {
    return !isPositive(remaining);
  }

  /**
   * Limita el monto cubierto al remanente y deja la marca TOPE_SUMA_ASEGURADA.
   * @rule R-014
   */
  cap(covered: Decimal, remaining: Decimal, observations: Observations): AdjustedAmount {
    if (covered.gt(remaining)) {
      return new AdjustedAmount(remaining, observations.add('TOPE_SUMA_ASEGURADA'));
    }
    return new AdjustedAmount(covered, observations);
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import { AdjustedAmount } from '../../model/AdjustedAmount.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import type { Observations } from '../../model/Observations.ts';
import { percentOf, zeroAmount } from '../../services/AmountMath.ts';

/** Retención impositiva (ramos distintos de VIDA sobre el umbral) y neto. */
export class WithholdingRule {
  /**
   * @rule R-015
   * @rule R-021
   */
  calculate(
    covered: Decimal,
    branch: string,
    params: BusinessParameters,
    observations: Observations,
  ): AdjustedAmount {
    if (branch === 'VIDA') {
      return new AdjustedAmount(zeroAmount(), observations);
    }
    const threshold = params.require('UMBRAL_RETENCION');
    if (!covered.gt(threshold)) {
      return new AdjustedAmount(zeroAmount(), observations);
    }
    const rate = params.require('TASA_RETENCION');
    return new AdjustedAmount(percentOf(covered, rate), observations.add('RETENCION_APLICADA'));
  }

  /**
   * net_amount = covered_amount - withholding_amount.
   * @rule R-015
   */
  netAmount(covered: Decimal, withholding: Decimal): Decimal {
    return covered.minus(withholding);
  }
}

