/** Alerta de sospecha de fraude. */
export class FraudSuspicionRule {
  /**
   * Sospechoso si ocurre en los primeros días de la póliza y lo reclamado alcanza el umbral.
   * @rule R-016
   * @rule R-021
   */
  isSuspicious(request: LiquidationRequest, params: BusinessParameters): boolean {
    const threshold = percentOf(request.coverage.limit, params.require('PCT_ALERTA_FRAUDE'));
    const maxDays = params.require('DIAS_ALERTA_FRAUDE');
    const daysSinceStart = request.claim.occurrenceDate.daysSince(request.policy.startDate);
    const earlyClaim = Decimal.of(daysSinceStart).lte(maxDays);
    return earlyClaim && request.claim.amountClaimed.gte(threshold);
  }
}

