export interface FinalDecision {
  readonly status: LiquidationStatus;
  readonly reasonCode: ApprovalReason;
}

/** Estado final con prioridades: fraude, tope automático, aprobación. */
export class FinalDecisionRule {
  /**
   * @rule R-016
   * @rule R-017
   */
  decide(fraudSuspected: boolean, netAmount: Decimal, params: BusinessParameters): FinalDecision {
    if (fraudSuspected) {
      return { status: 'PENDIENTE_APROBACION', reasonCode: 'SOSPECHA_FRAUDE' };
    }
    if (netAmount.gt(params.require('TOPE_AUTO_APROBACION'))) {
      return { status: 'PENDIENTE_APROBACION', reasonCode: 'SUPERA_TOPE_AUTOMATICO' };
    }
    return { status: 'APROBADA', reasonCode: 'LIQUIDACION_AUTOMATICA' };
  }
}

