export interface LiquidationRules {
  readonly eligibility: EligibilityPipeline;
  readonly baseAmount: BaseAmountRule;
  readonly deductible: DeductibleRule;
  readonly vipDiscount: VipDeductibleDiscountRule;
  readonly coveredAmount: CoveredAmountRule;
  readonly frequencyPenalty: FrequencyPenaltyRule;
  readonly sumInsuredCap: SumInsuredCapRule;
  readonly withholding: WithholdingRule;
  readonly fraud: FraudSuspicionRule;
  readonly finalDecision: FinalDecisionRule;
}

/** Servicio de dominio que orquesta la liquidación de un siniestro. */
export class ClaimLiquidationService {
  private readonly rules: LiquidationRules;

  constructor(rules: LiquidationRules) {
    this.rules = rules;
  }

  /**
   * Solo se liquidan siniestros REGISTRADO; un parámetro faltante aborta con ORA-20010.
   * @rule R-001
   * @rule R-002
   */
  liquidate(request: LiquidationRequest, params: BusinessParameters): LiquidationResult {
    if (request.claim.status !== 'REGISTRADO') {
      return LiquidationResult.failed('ORA-20001');
    }
    try {
      return this.liquidateRegistered(request, params);
    } catch (error) {
      if (error instanceof MissingParameterError) {
        return LiquidationResult.failed('ORA-20010');
      }
      throw error;
    }
  }

  /**
   * @rule R-018
   */
  private liquidateRegistered(request: LiquidationRequest, params: BusinessParameters): LiquidationResult {
    const eligibility = this.rules.eligibility.run(request, params);
    if (eligibility.rejectionReason !== null) {
      return LiquidationResult.rejected(eligibility.rejectionReason, eligibility.observations);
    }
    return this.calculate(request, params, eligibility.observations);
  }

  /**
   * @rule R-009
   * @rule R-010
   * @rule R-011
   * @rule R-012
   */
  private calculate(
    request: LiquidationRequest,
    params: BusinessParameters,
    observations: Observations,
  ): LiquidationResult {
    const base = this.rules.baseAmount.calculate(
      request.claim.amountClaimed,
      request.coverage.limit,
      observations,
    );
    const fixed = this.rules.deductible.calculate(base.amount, request.policy, params, base.observations);
    const deductible = this.rules.vipDiscount.apply(
      fixed.amount,
      request.customer.category,
      params,
      fixed.observations,
    );
    const covered = this.rules.coveredAmount.calculate(
      base.amount,
      deductible.amount,
      request.coverage.percentage,
    );
    if (this.rules.coveredAmount.isBelowDeductible(covered)) {
      return LiquidationResult.rejected('BAJO_DEDUCIBLE', deductible.observations);
    }
    return this.applyLimits(request, params, base.amount, deductible, covered);
  }

  /**
   * @rule R-013
   * @rule R-014
   */
  private applyLimits(
    request: LiquidationRequest,
    params: BusinessParameters,
    baseAmount: Decimal,
    deductible: AdjustedAmount,
    covered: Decimal,
  ): LiquidationResult {
    const penalized = this.rules.frequencyPenalty.apply(
      covered,
      request.history.recentLiquidatedClaimsCount,
      params,
      deductible.observations,
    );
    const remaining = this.rules.sumInsuredCap.remaining(
      request.policy.sumInsured,
      request.history.totalIndemnified,
    );
    if (this.rules.sumInsuredCap.isExhausted(remaining)) {
      return LiquidationResult.rejected('SUMA_ASEGURADA_AGOTADA', penalized.observations);
    }
    const capped = this.rules.sumInsuredCap.cap(penalized.amount, remaining, penalized.observations);
    return this.settle(request, params, baseAmount, deductible.amount, capped);
  }

  /**
   * @rule R-015
   * @rule R-016
   * @rule R-017
   */
  private settle(
    request: LiquidationRequest,
    params: BusinessParameters,
    baseAmount: Decimal,
    deductibleAmount: Decimal,
    capped: AdjustedAmount,
  ): LiquidationResult {
    const withholding = this.rules.withholding.calculate(
      capped.amount,
      request.policy.branch,
      params,
      capped.observations,
    );
    const net = this.rules.withholding.netAmount(capped.amount, withholding.amount);
    const fraud = this.rules.fraud.isSuspicious(request, params);
    const decision = this.rules.finalDecision.decide(fraud, net, params);
    return LiquidationResult.decided({
      status: decision.status,
      reasonCode: decision.reasonCode,
      baseAmount,
      deductibleAmount,
      coveredAmount: capped.amount,
      withholdingAmount: withholding.amount,
      netAmount: net,
      observations: withholding.observations,
    });
  }
}

