import type { LocalDate } from '../model/LocalDate.ts';
import { percentOf } from './AmountMath.ts';

const DAYS_IN_WEEK = 7;
const THURSDAY_OFFSET = 3;
const FIRST_WEEKEND_INDEX = 5;

/**
 * Cálculos obsoletos del legacy que ninguna ruta activa invoca.
 * Se conservan documentados para que el negocio decida si se descartan.
 * @deprecated No forman parte del flujo de liquidación.
 */
export class ObsoleteCalculations {
  /**
   * Deducible v1 (2009): FIJO = valor; PORCENTAJE = TRUNC(reclamado * valor / 100, 2) sobre lo reclamado.
   * @rule R-023
   */
  deductibleV1(deductibleType: string, deductibleValue: Decimal, amountClaimed: Decimal): Decimal {
    if (deductibleType === 'FIJO') {
      return deductibleValue;
    }
    return amountClaimed.times(deductibleValue).dividedBy(Decimal.of(100), 2, 'DOWN');
  }

  /**
   * IVA = ROUND(monto * TASA_IVA / 100, 2).
   * @rule R-023
   */
  vat(amount: Decimal, vatRate: Decimal): Decimal {
    return percentOf(amount, vatRate);
  }

  /**
   * Reserva técnica = ROUND(monto reclamado * FACTOR_INFLACION, 2).
   * @rule R-023
   */
  technicalReserve(amountClaimed: Decimal, inflationFactor: Decimal): Decimal {
    return amountClaimed.times(inflationFactor).setScale(2, 'HALF_UP');
  }

  /**
   * Día hábil: de lunes a viernes (no sábado ni domingo).
   * @rule R-023
   */
  isBusinessDay(date: LocalDate): boolean {
    const mondayBased = (((date.epochDay + THURSDAY_OFFSET) % DAYS_IN_WEEK) + DAYS_IN_WEEK) % DAYS_IN_WEEK;
    return mondayBased < FIRST_WEEKEND_INDEX;
  }
}

