import { Decimal } from '../../../domain/shared/decimal.ts';
import { LocalDate } from '../../../domain/model/LocalDate.ts';
import { InvalidInputError } from './InvalidInputError.ts';

const DECIMAL_PATTERN = /^-?\d+(\.\d+)?$/;
const INTEGER_PATTERN = /^\d+$/;
const TRUE_VALUES: readonly string[] = ['true', '1', 's', 'si', 'y', 'yes'];
const FALSE_VALUES: readonly string[] = ['false', '0', 'n', 'no', ''];

/** Lee y valida campos de texto del mapa de entrada. */
export class FieldReader {
  private readonly input: Record<string, string>;

  constructor(input: Record<string, string>) {
    this.input = input;
  }

  private raw(name: string): string {
    return (this.input[name] ?? '').trim();
  }

  text(name: string): string {
    return this.raw(name);
  }

  /** Decimal con la escala indicada; vacío equivale a 0. */
  decimal(name: string, scale: number): Decimal {
    const value = this.raw(name);
    if (value === '') {
      return Decimal.of('0').setScale(scale, 'HALF_UP');
    }
    if (!DECIMAL_PATTERN.test(value)) {
      throw new InvalidInputError(name);
    }
    return Decimal.of(value).setScale(scale, 'HALF_UP');
  }

  /** Entero no negativo; vacío equivale a 0. */
  integer(name: string): number {
    const value = this.raw(name);
    if (value === '') {
      return 0;
    }
    if (!INTEGER_PATTERN.test(value)) {
      throw new InvalidInputError(name);
    }
    return parseInt(value, 10);
  }

  boolean(name: string): boolean {
    const value = this.raw(name).toLowerCase();
    if (TRUE_VALUES.includes(value)) {
      return true;
    }
    if (FALSE_VALUES.includes(value)) {
      return false;
    }
    throw new InvalidInputError(name);
  }

  date(name: string): LocalDate {
    const parsed = LocalDate.parse(this.raw(name));
    if (parsed === null) {
      throw new InvalidInputError(name);
    }
    return parsed;
  }
}

import { Decimal } from '../../../domain/shared/decimal.ts';
import { BusinessParameters } from '../../../domain/model/BusinessParameters.ts';

const PARAMETER_CODES: readonly string[] = [
  'DIAS_MAX_DENUNCIA',
  'DIAS_MAX_DENUNCIA_VIDA',
  'DEDUCIBLE_MINIMO',
  'PCT_DESCUENTO_DED_VIP',
  'TOLERANCIA_MORA_VIP',
  'MAX_SINIESTROS_ANUAL',
  'PCT_PENALIZACION_SINIEST',
  'UMBRAL_RETENCION',
  'TASA_RETENCION',
  'TOPE_AUTO_APROBACION',
  'DIAS_ALERTA_FRAUDE',
  'PCT_ALERTA_FRAUDE',
];

const PAIR_PATTERN = /"?([A-Z][A-Z0-9_]*)"?\s*[:=]\s*"?(-?\d+(?:\.\d+)?)"?/g;
const NUMBER_PATTERN = /^-?\d+(\.\d+)?$/;

/**
 * Convierte el texto de parámetros ('CLAVE=valor;...' o JSON simple) en BusinessParameters.
 * No usa números de coma flotante: los valores se conservan como texto decimal exacto.
 * Los códigos también pueden venir como campos sueltos de la entrada.
 */
export function parseBusinessParameters(
  text: string,
  input: Record<string, string>,
): BusinessParameters {
  const values = new Map<string, Decimal>();
  for (const match of text.matchAll(PAIR_PATTERN)) {
    values.set(match[1] ?? '', Decimal.of(match[2] ?? '0'));
  }
  for (const code of PARAMETER_CODES) {
    const direct = (input[code] ?? '').trim();
    if (!values.has(code) && NUMBER_PATTERN.test(direct)) {
      values.set(code, Decimal.of(direct));
    }
  }
  return new BusinessParameters(values);
}

