export type MappingResult =
  | { readonly ok: true; readonly request: LiquidationRequest; readonly params: BusinessParameters }
  | { readonly ok: false; readonly field: string };

/** Adaptador de entrada: Record<string,string> a tipos del dominio. */
export class StringRequestMapper {
  map(input: Record<string, string>): MappingResult {
    try {
      const reader = new FieldReader(input);
      return {
        ok: true,
        request: this.buildRequest(reader),
        params: parseBusinessParameters(input['params'] ?? '', input),
      };
    } catch (error) {
      if (error instanceof InvalidInputError) {
        return { ok: false, field: error.field };
      }
      throw error;
    }
  }

  private buildRequest(reader: FieldReader): LiquidationRequest {
    return {
      claim: this.claim(reader),
      policy: this.policy(reader),
      customer: this.customer(reader),
      coverage: this.coverage(reader),
      history: this.history(reader),
    };
  }

  private claim(reader: FieldReader): ClaimData {
    return {
      status: reader.text('claim_status'),
      amountClaimed: reader.decimal('amount_claimed', 2),
      occurrenceDate: reader.date('occurrence_date'),
      reportDate: reader.date('report_date'),
    };
  }

  private policy(reader: FieldReader): PolicyData {
    return {
      status: reader.text('policy_status'),
      branch: reader.text('policy_branch'),
      startDate: reader.date('policy_start_date'),
      endDate: reader.date('policy_end_date'),
      sumInsured: reader.decimal('sum_insured', 2),
      deductibleType: reader.text('deductible_type'),
      deductibleValue: reader.decimal('deductible_value', 2),
      pendingPremium: reader.decimal('pending_premium', 2),
    };
  }

  private customer(reader: FieldReader): CustomerData {
    return { category: reader.text('customer_category') };
  }

  private coverage(reader: FieldReader): CoverageData {
    return {
      found: reader.boolean('coverage_found'),
      limit: reader.decimal('coverage_limit', 2),
      percentage: reader.decimal('coverage_percentage', 2),
      waitingDays: reader.integer('waiting_days'),
    };
  }

  private history(reader: FieldReader): ClaimHistory {
    return {
      recentLiquidatedClaimsCount: reader.integer('recent_liquidated_claims_count'),
      totalIndemnified: reader.decimal('total_indemnified', 2),
    };
  }
}

