/** Composition root: ensambla dominio, aplicación e infraestructura. */
function composeUseCase(): LiquidateClaimUseCase {
  const eligibility = new EligibilityPipeline([
    new ActivePolicyCheck(),
    new CoverageWindowCheck(),
    new ReportDeadlineCheck(),
    new ContractedCoverageCheck(),
    new WaitingPeriodCheck(),
    new PremiumArrearsCheck(),
  ]);
  const service = new ClaimLiquidationService({
    eligibility,
    baseAmount: new BaseAmountRule(),
    deductible: new DeductibleRule(),
    vipDiscount: new VipDeductibleDiscountRule(),
    coveredAmount: new CoveredAmountRule(),
    frequencyPenalty: new FrequencyPenaltyRule(),
    sumInsuredCap: new SumInsuredCapRule(),
    withholding: new WithholdingRule(),
    fraud: new FraudSuspicionRule(),
    finalDecision: new FinalDecisionRule(),
  });
  return new LiquidateClaimUseCase(service, new InMemoryLiquidationAudit());
}

/** Punto de entrada: recibe y devuelve todos los valores como cadenas. */
export function execute(input: Record<string, string>): Record<string, string> {
  const resultMapper = new StringResultMapper();
  const mapping = new StringRequestMapper().map(input);
  if (!mapping.ok) {
    return resultMapper.invalidInput();
  }
  const result = composeUseCase().execute(mapping.request, mapping.params);
  return resultMapper.toOutput(result);
}

